        int node_id = find_node_for_tensor(mgr.graph, param)
        if node_id >= 0  node_id < len(mgr.graph.nodes) {
            tensor grad_t {
                data: copy_tensor(mgr.graph.nodes[node_id].output.grad),
                grad: [],
