    mgr.param_gradients = {}
    for i in 0..len(mgr.graph.nodes) {
        if len(mgr.graph.nodes[i].output.grad) > 0 {
            mgr.graph.nodes[i].output.grad = zeros_like_array(len(mgr.graph.nodes[i].output.grad))
        }
    }
