struct gradient_manager {
    computation_graph graph
    map[int]tensor param_gradients
func new_gradient_manager() gradient_manager {
    gradient_manager {
        graph: new_graph(),
        param_gradients: {},
    }

func compute_gradients(
    gradient_manager mgr,
    tensor loss,
    []tensor parameters
