    if x == 0.0 || x == 1.0 { return x }
    float guess = x / 2.0
    int iterations = 20
    for i in 0..iterations {
        float new_guess = (guess + x / guess) / 2.0
        if abs_float(new_guess - guess) < 1e-10 {
            break
        }
        guess = new_guess
    }
    guess
